        "views/res_config_settings_views.xml",
        "views/tag_views.xml",
        "views/similarity_views.xml",
        "views/question_views.xml",
        "views/bank_import_views.xml",
        "views/delete_wizard_views.xml",
        "views/simple_import_views.xml",
        "views/llm_usage_views.xml",
        "views/llm_dashboard_views.xml",
        "views/hr_applicant_views.xml",
        "views/prompt_views.xml",
        "views/task_template_views.xml",
        "views/studio_form_views.xml",
        "views/assessment_views.xml",
        "views/dashboard_views.xml",
